<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Müsaitlik takvimi</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:950px;margin:35px auto;padding:0 18px}.panel{background:white;padding:22px;border-radius:14px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}label{font-size:13px;font-weight:700}input,select{display:block;width:100%;box-sizing:border-box;padding:11px;border:1px solid #dfe6e0;border-radius:8px;margin-top:6px;font:inherit}button{background:#176b50;color:white;border:0;padding:11px 15px;border-radius:8px;font-weight:700}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #edf0ed}.muted{color:#6d796f}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}}</style></head><body><main class="wrap"><h1>Müsaitlik ve fiyat takvimi</h1><p><?= e($property['title']) ?></p><section class="panel"><h2>Tarih aralığı ekle</h2><form method="post" action="<?= e($saveUrl) ?>"><?= csrf_field() ?><input type="hidden" name="property_id" value="<?= (int)$property['id'] ?>"><div class="grid"><label>Başlangıç<input type="date" name="date_from" required></label><label>Bitiş (dahil değil)<input type="date" name="date_to" required></label><label>Durum<select name="status"><option value="blocked">Kapalı / müsait değil</option><option value="available">Müsait</option></select></label><label>Gecelik özel fiyat<input type="number" name="nightly_price" min="0" step=".01" placeholder="Boş bırak: temel fiyat"></label></div><p><button>Takvime kaydet</button></p></form></section><section class="panel"><h2>Kayıtlı tarih aralıkları</h2><table><thead><tr><th>Başlangıç</th><th>Bitiş</th><th>Durum</th><th>Özel fiyat</th><th></th></tr></thead><tbody><?php foreach($ranges as $range): ?><tr><td><?= e($range['date_from']) ?></td><td><?= e($range['date_to']) ?></td><td><?= e($range['status']) ?></td><td><?= $range['nightly_price']!==null?e(number_format((float)$range['nightly_price'],0,',','.')):'Temel fiyat' ?></td><td><form method="post" action="<?= e($deleteUrl) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$range['id'] ?>"><input type="hidden" name="property_id" value="<?= (int)$property['id'] ?>"><button style="background:#a43">Sil</button></form></td></tr><?php endforeach; ?><?php if(!$ranges): ?><tr><td colspan="5">Henüz takvim kuralı yok.</td></tr><?php endif; ?></tbody></table></section><p><a href="<?= e($backUrl) ?>">← Geri</a></p></main></body></html>